    if (run.runType === 'long')
        tags.push('long run');
    if (run.runType === 'interval')
        tags.push('intervals');
    if (run.runType === 'tempo')
        tags.push('tempo');
    if (intensity === 'high')
        tags.push('high intensity');
    if (rpe >= 8)
        tags.push('hard effort');
    if (rpe <= 3)
        tags.push('easy effort');
    if (avgHR > 170)
        tags.push('high HR');
    if (cadence > 0 && cadence >= 180)
        tags.push('efficient');
    if (cadence > 0 && cadence < 160)
        tags.push('low cadence');
