        return 'recovery';
    if (/easy|이지/.test(raw))
        return 'easy';
    if (/tempo|템포/.test(raw))
        return 'tempo';
    if (/interval|인터벌/.test(raw))
        return 'interval';
    if (/long|lsd|장거리/.test(raw))
        return 'long';
    if (/race|competition|대회/.test(raw))
        return 'race';
    if (/hkwout|hkworkoutactivitytyperunning|outdoor run|indoor run|running|\brun\b|러닝/.test(raw))
        return 'easy';
    const distance = readNum(run?.distance_km, run?.distanceKm, run?.distance);
    const duration = readNum(run?.duration_seconds, run?.durationSeconds, run?.duration);
    const pace = readNum(run?.pace_sec_per_km, run?.paceSecPerKm, run?.pace) || (distance > 0 && duration > 0 ? duration / distance : 0);
    const recentPaces = recentRuns.map(r => readNum(r?.pace_sec_per_km, r?.paceSecPerKm, r?.pace)).filter(Boolean);
    const recentAvgPace = recentPaces.length > 0 ? recentPaces.reduce((a, b) => a + b, 0) / recentPaces.length : 0;
    if (duration > 70 * 60 || distance > 12)
        return 'long';
    if (pace > 0 && recentAvgPace > 0 && pace < recentAvgPace * 0.94)
        return 'tempo';
