function getEffortLevel(run, recentRuns = []) {
    const rpe = readNum(run?.rpe, run?.perceivedEffort);
    const trainingLoad = readNum(run?.training_load, run?.trainingLoad);
    const avgHr = readNum(run?.avg_hr, run?.avgHeartRate, run?.averageHeartRate);
    const duration = readNum(run?.duration_seconds, run?.durationSeconds, run?.duration);
    const distance = readNum(run?.distance_km, run?.distanceKm, run?.distance);
    const pace = readNum(run?.pace_sec_per_km, run?.paceSecPerKm, run?.pace) || (distance > 0 && duration > 0 ? duration / distance : 0);
    const type = normalizeRunType(run, recentRuns);
    let score = 40;
    let reason = 'Estimated from run type and available metrics.';
    if (rpe > 0) {
        score = rpe * 10;
        reason = 'Based primarily on RPE.';
    }
    else if (trainingLoad > 0) {
        score = Math.min(100, Math.round(trainingLoad / 8));
        reason = 'Based on normalized training load.';
    }
    else {
        const base = {
            recovery: 25, easy: 40, long: 55, tempo: 70, interval: 85, race: 90, unknown: 40,
        };
        score = base[type];
        reason = 'Estimated from normalized run type.';
    }
    const hrSamples = recentRuns.map(r => readNum(r?.avg_hr, r?.avgHeartRate, r?.averageHeartRate)).filter(Boolean);
    const paceSamples = recentRuns.map(r => readNum(r?.pace_sec_per_km, r?.paceSecPerKm, r?.pace)).filter(Boolean);
    const recentAvgHr = hrSamples.length ? hrSamples.reduce((a, b) => a + b, 0) / hrSamples.length : 0;
    const recentAvgPace = paceSamples.length ? paceSamples.reduce((a, b) => a + b, 0) / paceSamples.length : 0;
    if (avgHr > 0 && recentAvgHr > 0 && avgHr > recentAvgHr + 8)
        score += 5;
    if (pace > 0 && recentAvgPace > 0 && pace < recentAvgPace)
        score += 5;
    if (duration > 70 * 60)
        score += 5;
    if (duration > 0 && duration < 20 * 60)
        score -= 5;
    score = Math.max(0, Math.min(100, Math.round(score)));
    const label = score <= 35 ? 'LOW' : score <= 60 ? 'MODERATE' : score <= 80 ? 'HARD' : 'VERY HARD';
    return { score, label, reason };
}
