function getRunFeedback(run, recentRuns = []) {
    // Prefer the existing rule-based feedback already saved on the run
    if (run.feedback && run.feedback.trim().length > 0)
        return run.feedback;
    // Otherwise generate a short fallback
    const score = getRunIntensityScore(run, recentRuns);
    // Specific gentle nudges
    if (!run.cadence)
        return 'Cadence data is missing. Add it for deeper rhythm insights.';
    // HR vs pace check
    const hrSamples = recentRuns.filter(r => typeof r.avgHeartRate === 'number' && r.avgHeartRate > 0);
    const recentAvgHR = hrSamples.length > 0
        ? hrSamples.reduce((a, r) => a + (r.avgHeartRate ?? 0), 0) / hrSamples.length : 0;
    if (run.avgHeartRate && recentAvgHR > 0 && run.avgHeartRate > recentAvgHR * 1.07) {
        return 'Heart rate is elevated for this pace.';
    }
    // By run type and score
    if (run.runType === 'recovery')
        return 'Light aerobic effort. Good for recovery.';
    if (run.runType === 'easy')
        return 'Stable easy run. Build your baseline.';
    if (run.runType === 'tempo')
        return 'Tempo effort detected. Watch recovery after this session.';
    if (run.runType === 'interval')
        return 'High intensity session. Keep the next run easier.';
    if (run.runType === 'long')
        return 'Long aerobic block. Prioritize nutrition and sleep.';
    if (score >= 80)
        return 'High intensity session. Keep the next run easier.';
    if (score >= 60)
        return 'Solid effort. Maintain consistency in upcoming sessions.';
    return 'Run logged. Build your baseline for deeper insights.';
}
