// Auto-classify run type
// ─────────────────────────────────────────────────────────────
/**
 * Automatically classify a run type from distance, HR, and pace
 * relative to recent training history.
 */
function classifyRunType(run, recentRuns = []) {
    const distance = Number(run.distance || 0);
    const avgHr = Number(run.avgHeartRate || 0);
    const pace = Number(run.pace || 0);
    const recentAvgDistance = recentRuns.length > 0
        ? recentRuns.reduce((s, r) => s + Number(r.distance || 0), 0) / recentRuns.length
        : 0;
    const recentAvgPace = recentRuns.filter(r => r.pace && r.pace > 0).length > 0
        ? recentRuns.filter(r => r.pace && r.pace > 0).reduce((s, r) => s + (r.pace ?? 0), 0) / recentRuns.filter(r => r.pace && r.pace > 0).length
        : 0;
    const isLongDistance = distance >= 10 || (recentAvgDistance > 0 && distance >= recentAvgDistance * 1.4);
    // Long Run: relatively long distance, moderate HR
    if (isLongDistance && (avgHr === 0 || avgHr < 165))
        return 'long';
    // Tempo Run: fast pace, high HR, minimum distance
    if (avgHr >= 155 && distance >= 4)
        return 'tempo';
    if (pace > 0 && recentAvgPace > 0 && pace < recentAvgPace * 0.92 && distance >= 4)
        return 'tempo';
    // Recovery Run: short distance, low HR
    if (distance <= 5 && avgHr > 0 && avgHr <= 135)
        return 'recovery';
    return 'easy';
}

