function loadAppState() {
    try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (raw) {
            return JSON.parse(raw);
        }
    }
    catch { /* empty */ }
    const defaultState = {
        runs: generateSampleData(),
        profile: {
            name: 'Alex Morgan',
            location: 'San Francisco, CA',
            joinDate: new Date(Date.now() - 180 * 24 * 60 * 60 * 1000).toISOString(),
            avatarInitials: 'AM',
        },
    };
    saveAppState(defaultState);
    return defaultState;
}
function saveAppState(state) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}
function addRun(state, runData) {
    const pace = calcPace(runData.duration, runData.distance);
    const speed = calcSpeed(runData.duration, runData.distance);
    const trainingLoad = calcTrainingLoad(runData.rpe, runData.duration);
    const intensity = calcIntensity(runData.rpe, runData.avgHeartRate);
    const recentRuns = [...state.runs].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    // Auto-classify run type on save for all entry/import methods.
    const autoRunType = classifyRunType({ distance: runData.distance, avgHeartRate: runData.avgHeartRate, pace, duration: runData.duration }, recentRuns.slice(0, 10));
    const classifiedData = { ...runData, runType: autoRunType };
    const partial = { ...classifiedData, pace, intensity };
    const tags = generateTags(partial);
    const feedback = generateFeedback(partial, recentRuns);
    const newRun = {
        id: generateId(),
        ...classifiedData,
        pace,
        speed,
        trainingLoad,
        intensity,
        tags,
        feedback,
    };
    const newState = { ...state, runs: [newRun, ...state.runs] };
    saveAppState(newState);
    return newState;
}
function updateRun(state, id, runData) {
    const updatedRuns = state.runs.map(r => {
        if (r.id !== id)
            return r;
        const merged = { ...r, ...runData };
        const pace = calcPace(merged.duration, merged.distance);
        const speed = calcSpeed(merged.duration, merged.distance);
        const trainingLoad = calcTrainingLoad(merged.rpe, merged.duration);
        const intensity = calcIntensity(merged.rpe, merged.avgHeartRate);
        const recentRuns = state.runs.filter(x => x.id !== id).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        const partial = { ...merged, pace, intensity };
        const tags = generateTags(partial);
        const feedback = generateFeedback(partial, recentRuns);
        return { ...merged, pace, speed, trainingLoad, intensity, tags, feedback };
    });
    const newState = { ...state, runs: updatedRuns };
    saveAppState(newState);
    return newState;
}
function deleteRun(state, id) {
    const newState = { ...state, runs: state.runs.filter(r => r.id !== id) };
    saveAppState(newState);
    return newState;
}

const AppContext = createContext(null);
function AppProvider({ children }) {
    const [state, setState] = useState(loadAppState);
    const addRunEntry = useCallback((run) => {
        let newRun = null;
        setState(prev => {
            const next = addRun(prev, run);
            newRun = next.runs[0];
            return next;
        });
        return newRun;
    }, []);
    const updateRunEntry = useCallback((id, data) => {
        setState(prev => updateRun(prev, id, data));
    }, []);
    const deleteRunEntry = useCallback((id) => {
        setState(prev => deleteRun(prev, id));
    }, []);
    const updateProfile = useCallback((profile) => {
        setState(prev => {
            const next = { ...prev, profile: { ...prev.profile, ...profile } };
            saveAppState(next);
            return next;
        });
    }, []);
    const updateBaseline = useCallback((baseline) => {
        setState(prev => {
            const next = { ...prev, trainingBaseline: baseline };
            saveAppState(next);
            return next;
        });
    }, []);
    return (jsx(AppContext.Provider, { value: { state, addRunEntry, updateRunEntry, deleteRunEntry, updateProfile, updateBaseline }, children: children }));
}
function useApp() {
    const ctx = useContext(AppContext);
    if (!ctx)
        throw new Error('useApp must be used within AppProvider');
    return ctx;
}

